/* 算法逻辑 */
function getResult(s, k) {
  if (k <= 0) return -1;

  s += "0";

  let count = {};

  let b = s[0];
  let len = 1;

  for (let i = 1; i < s.length; i++) {
    const c = s[i];

    if (b == c) {
      len++;
    } else {
      if (count[b] == undefined || count[b] < len) {
        count[b] = len;
      }
      len = 1;
      b = c;
    }
  }

  const arr = Object.values(count);

  if (k > arr.length) {
    return -1;
  } else {
    arr.sort((a, b) => b - a);
    return arr[k - 1];
  }
}

